INSERT INTO `project_showcase_attachments` VALUES ('2505eeb9-8114-4061-8a98-276fe46f8063','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Manual Operador v2.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',11878,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:30:00.514'),('2592f4e1-61e3-4b6b-9104-d7dfd4150a44','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Briefing Permissoes.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',12715,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:29:59.943'),('32c5e117-5ec1-4206-a3fd-d4e97b75e6ae','aea8edc1-568e-4ac5-8b72-8bd960f0a865','f943b045-8dbf-44e6-b103-e8b44a875f47','Captura de tela 2026-06-10 152147.png','image/png',162949,'data:image/png;base64,','2026-06-10 18:29:58.254'),('37eaa2c2-ead8-49a7-a42b-4d07d108596e','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Briefing Desenvolvedores.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',13972,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:30:00.215'),('4297ab25-c65f-4173-8be7-8ce3b0f9e80e','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Ordem de Partida.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',13238,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:29:59.180'),('63389577-297d-418a-bc26-8420765caf33','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Futuro do sistema - briefing.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',14947,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:29:59.680'),('921053b4-fc53-4faa-af51-c3990cafea7f','a9d6376c-c0b1-41e6-a001-0dbbf4d17114','f943b045-8dbf-44e6-b103-e8b44a875f47','Captura de tela 2026-06-17 141015.png','image/png',22612,'data:image/png;base64,','2026-06-17 18:40:46.767'),('a21ea8f0-ac9a-40f2-8c6d-354db29dac21','aea8edc1-568e-4ac5-8b72-8bd960f0a865','f943b045-8dbf-44e6-b103-e8b44a875f47','Captura de tela 2026-06-10 152219.png','image/png',170560,'data:image/png;base64,','2026-06-10 18:30:22.810');
INSERT INTO `project_showcase_attachments` VALUES ('aadf4dd8-b6d5-43a6-a5da-64e593a8e4a3','aea8edc1-568e-4ac5-8b72-8bd960f0a865','f943b045-8dbf-44e6-b103-e8b44a875f47','Captura de tela 2026-06-10 152101.png','image/png',397116,'data:image/png;base64,','2026-06-10 18:30:31.432'),('b9615c18-2bc4-4034-a544-cf98dbfb40bb','aea8edc1-568e-4ac5-8b72-8bd960f0a865','f943b045-8dbf-44e6-b103-e8b44a875f47','Captura de tela 2026-06-10 152111.png','image/png',11826,'data:image/png;base64,','2026-06-10 18:30:13.053'),('bad06921-d0dd-4c35-8142-849595fc3a49','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Especificacao Tecnica.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',15686,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:29:48.714');
INSERT INTO `project_showcase_attachments` VALUES ('ccb04f79-a956-4cec-8d7f-219af9a9cd14','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Controle Custo Pessoas.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',535951,'data:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;base64,','2026-06-11 09:30:01.850'),('f7de5ac3-7bfb-43cf-b1b9-136442038bf7','a8266323-6c66-480d-bb73-1c31d6b15fb6','c87008d2-0a62-4498-b39e-5e2f6f44d4bd','Manual Gestora Antifraude.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document',11441,'data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,','2026-06-11 09:30:00.802');
